import java.util.*;
import java.math.BigInteger;

class Solution {
    public List<List<String>> cardRangePart2(String BIN, List<List<String>> info) {
        String low = BIN + "0000000000", high = BIN + "9999999999";
        List<List<String>> ivs = new ArrayList<>();
        for (List<String> iv : info) ivs.add(new ArrayList<>(List.of(BIN + iv.get(0), BIN + iv.get(1), iv.get(2))));
        ivs.sort((a, b) -> a.get(0).compareTo(b.get(0)));
        if (ivs.isEmpty()) return ivs;
        ivs.get(0).set(0, low);
        ivs.get(ivs.size() - 1).set(1, high);
        for (int i = 0; i < ivs.size() - 1; i++) {
            BigInteger nxt = new BigInteger(ivs.get(i + 1).get(0)).subtract(BigInteger.ONE);
            String s = nxt.toString();
            while (s.length() < 16) s = "0" + s;
            ivs.get(i).set(1, s);
        }
        return ivs;
    }
}

#include <bits/stdc++.h>
using namespace std;

class Solution {
    string decrementString(string s) {
        int i = s.size() - 1;
        while (i >= 0 && s[i] == '0') { s[i] = '9'; i--; }
        if (i >= 0) s[i]--;
        return s;
    }
public:
    vector<vector<string>> cardRangePart2(string BIN, vector<vector<string>>& info) {
        string low = BIN + string(10, '0'), high = BIN + string(10, '9');
        vector<vector<string>> ivs;
        for (auto& iv : info) ivs.push_back({BIN + iv[0], BIN + iv[1], iv[2]});
        sort(ivs.begin(), ivs.end());
        if (ivs.empty()) return ivs;
        ivs.front()[0] = low; ivs.back()[1] = high;
        for (int i = 0; i + 1 < (int)ivs.size(); i++) {
            ivs[i][1] = decrementString(ivs[i + 1][0]);
        }
        return ivs;
    }
};
